{
  "sop_id": "SOP-021",
  "title": "Employee Document Verification",
  "steps": [
    {"step_id": "S1", "name": "Create ticket", "role": "Executor", "type": "intake"},
    {"step_id": "S2", "name": "Check checklist completeness", "role": "Executor", "type": "work"},
    {"step_id": "S3", "name": "Verify identity and address proofs", "role": "Executor", "type": "work"},
    {"step_id": "S4", "name": "Send education and employment confirmations", "role": "Executor", "type": "work"},
    {"step_id": "S5", "name": "Cross-check documents", "role": "Executor", "type": "work"},
    {"step_id": "S6", "name": "Record verification status and submit", "role": "Executor", "type": "work"},
    {"step_id": "D1", "name": "Credential confirmation", "role": "Executor", "type": "decision"},
    {"step_id": "A1", "name": "Incharge approval", "role": "Incharge", "type": "approval"},
    {"step_id": "R1", "name": "Rework on rejection", "role": "Executor", "type": "rework"},
    {"step_id": "A2", "name": "Lead approval (discrepancies only)", "role": "Lead", "type": "approval"}
  ],
  "approvals": [
    {"stage": "Incharge", "condition": "always", "evidence": "See RACI table"},
    {"stage": "Lead", "condition": "discrepancies only", "evidence": "See RACI table"}
  ],
  "dependencies": [
    {"dep_id": "D1", "provider": "Issuer / BGV agency", "item": "Credential confirmation", "parallel_group": "P1", "evidence": "See RACI table"}
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.9
}
